import { useRef } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { CheckPinNumResponseDTO, PinNumRequestDTO } from '~/entities/pin/api/dtos/types';
import { useGetCheckPinNumMutation } from '~/entities/pin/api/use-get-check-pin-num-mutation';
import { getLatestTranskeyModel } from '~/entities/pin/lib/get-latest-transkey-model';
import { getUserRes } from '~/entities/user/api/use-get-cstmr-query';
import i18n from '~/shared/i18n/i18n';
import { useMaxFailureHandler } from '~/shared/lib/hooks/use-max-failure-handler';
import { PIN_CONSTANTS } from './constants';

export const usePinInput = () => {
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { mutateAsync: getCheckPinNum } = useGetCheckPinNumMutation({ throwOnError: false });
  const { handleMaxFailure } = useMaxFailureHandler();

  const isFail = useRef(false);

  // Store에서 필요한 상태와 액션 가져오기
  const [
    incorrectPinCount,
    handleShuffle,
    triggerCompleteInput,
    isPinEmpty,
    isPinLengthInvalid,
    shouldShowPinError,
    calculateFailCount,
    handleErrorMessage,
    setIsError,
  ] = useStore(
    useShallow((s) => [
      s.pinSlice.incorrectPinCount ?? 0,
      s.pinSlice.handleShuffle,
      s.pinSlice.triggerCompleteInput,
      s.pinSlice.isPinEmpty,
      s.pinSlice.isPinLengthInvalid,
      s.pinSlice.shouldShowPinError,
      s.pinSlice.calculateFailCount,
      s.pinSlice.handleErrorMessage,
      s.pinSlice.setIsError,
    ]),
  );
  // 비밀번호 인증
  const handleInput = async () => {
    const userRes = getUserRes();
    const failCnt = calculateFailCount(incorrectPinCount);

    const handlePinError = () => {
      handleErrorMessage(i18n.t('pin:errorDifferentInputPin', { cnt: failCnt + 1 }));

      const isMaxFailureReached = failCnt > PIN_CONSTANTS.MAX_INCORRECT_COUNT;
      isMaxFailureReached && handleMaxFailure(state);
    };

    const handleInvalidPinLength = () => {
      const shouldDisplayError = isPinEmpty() && shouldShowPinError(failCnt, isFail.current);
      shouldDisplayError && handlePinError();

      setIsError(false);
      return undefined;
    };

    // Early return if pin length is invalid
    const isPinValid = !isPinLengthInvalid();
    if (!isPinValid) {
      return handleInvalidPinLength();
    }

    // 간편비밀번호 검증 로직
    const newUserParam: PinNumRequestDTO = {
      tbCstmrMastr: {
        cstmrNo: userRes?.tbCstmrMastr?.cstmrNo,
        pin: '',
      },
      transkeyModel: getLatestTranskeyModel(userRes?.transkeyModel),
    };

    // 핀번호 검증
    const validatePin = async () => {
      try {
        const ret = await getCheckPinNum(newUserParam);
        return ret ?? ({} as CheckPinNumResponseDTO);
      } catch (e: any) {
        return {} as CheckPinNumResponseDTO;
      }
    };

    const response = await validatePin();

    const handleSuccessfulAuth = () => {
      // Update JWT token in store when we receive a valid accessToken
      const { setJwt } = useStore.getState().authSlice;
      setJwt(response.accessToken);

      // 검증 성공 - 스토어의 콜백 트리거 사용
      triggerCompleteInput();
      handleShuffle();

      return response;
    };

    const handleFailedAuth = () => {
      isFail.current = true;
      handlePinError();
      return undefined;
    };

    return response.accessToken ? handleSuccessfulAuth() : handleFailedAuth();
  };

  return { handleInput };
};
