import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { PIN_CONSTANTS } from './constants';

export const useResetPin = () => {
  const { openAlertDialog } = useAlertDialog();
  const [
    pin,
    isSequentialOrSameNumber,
    fnChkUserData,
    resetPropsOnError,
    setPropsOnSecondStep,
    handleErrorMessage,
    prevPin,
    incorrectPinCount,
    setIncorrectPinCount,
    step,
    setPropsOnCompleteStep,
  ] = useStore(
    useShallow((s) => [
      s.pinSlice.pin,
      s.pinSlice.isSequentialOrSameNumber,
      s.pinSlice.fnChkUserData,
      s.pinSlice.resetPropsOnError,
      s.pinSlice.setPropsOnSecondStep,
      s.pinSlice.handleErrorMessage,
      s.pinSlice.prevPin,
      s.pinSlice.incorrectPinCount,
      s.pinSlice.setIncorrectPinCount,
      s.pinSlice.step,
      s.pinSlice.setPropsOnCompleteStep,
    ]),
  );

  const resetPinStepOne = () => {
    const isPinInvalid = isSequentialOrSameNumber(pin) || fnChkUserData(pin);

    const resetProps = () =>
      resetPropsOnError({
        title: i18n.t('pin:titleResetPin'),
        message: i18n.t('pin:messageResetPin'),
      });

    const handleInvalidPin = () => {
      handleErrorMessage(i18n.t('pin:messageSetPin'));
      openAlertDialog({
        message: i18n.t('pin:errorResetPin'),
        onConfirmClick: resetProps,
      });
    };

    const handleValidPin = () => {
      setPropsOnSecondStep({
        title: i18n.t('pin:titleResetPinConfirm'),
        message: i18n.t('pin:messageResetPinConfirm'),
      });
    };

    return isPinInvalid ? handleInvalidPin() : handleValidPin();
  };

  const resetPinStepTwo = () => {
    const isPinMatching = prevPin === pin;

    const handleMatchingPin = () => {
      setPropsOnCompleteStep({
        title: i18n.t('pin:titleResetPin'),
        message: i18n.t('pin:messageResetPin'),
      });
    };

    const handleNonMatchingPin = () => {
      const newIncorrectCount = incorrectPinCount + 1;
      setIncorrectPinCount(newIncorrectCount);

      const msg = i18n.t('pin:errorDifferentInputPin', { cnt: incorrectPinCount + 1 });
      handleErrorMessage(msg);

      const isMaxIncorrectReached = newIncorrectCount > PIN_CONSTANTS.MAX_INCORRECT_COUNT;

      if (isMaxIncorrectReached) {
        openAlertDialog({
          message: i18n.t('pin:errorMaxIncorrectPin'),
          onConfirmClick: () => {
            resetPropsOnError({
              title: i18n.t('pin:titleResetPin'),
              message: i18n.t('pin:messageResetPin'),
            });
          },
        });
      }
    };

    return isPinMatching ? handleMatchingPin() : handleNonMatchingPin();
  };

  const handleResetPin = () => {
    step === PIN_CONSTANTS.STEP.FIRST ? resetPinStepOne() : resetPinStepTwo();
  };

  return { handleResetPin };
};
