import { useEffect, memo, useRef } from 'react';
import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { TransKeyModel } from '~/entities/pin/api/dtos/types';
import { getLatestTranskeyModel } from '~/entities/pin/lib/get-latest-transkey-model';
import { useCreatePin } from '~/entities/pin/lib/use-create-pin';
import { usePinInput } from '~/entities/pin/lib/use-pin-input';
import { useResetPin } from '~/entities/pin/lib/use-reset-pin';
import { useVerifyPin } from '~/entities/pin/lib/use-verify-pin';
import { setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { VerificationType, PinInteractionMode } from '~/shared/api/dtos/enums';
import { useNavigate } from '~/shared/lib/hooks';
import { useScript } from '~/shared/lib/hooks/use-script';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';

// 간소화된 props
export type NumberPadProps = {
  type?: PinInteractionMode;
};

export const PinKeyboard = memo(function NumberPad(props: NumberPadProps) {
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { navigate } = useNavigate();
  const inputRef = useRef<HTMLInputElement>(null);
  const { handleCreatePin } = useCreatePin();
  const { handleResetPin } = useResetPin();
  const { handleInput } = usePinInput();
  const { handleVerifyPin } = useVerifyPin();
  const [isLoading1] = useScript('/transkey_mobile/transkey.js');
  const [isLoading2] = useScript('/transkey_mobile/TranskeyLibPack_op.js');
  const [isLoading3] = useScript('/transkey_mobile/rsa_oaep_files/rsa_oaep-min.js');
  const [isLoading4] = useScript('/transkey_mobile/jsbn/jsbn-sha2-min.js');
  const [isLoading5] = useScript('/transkey_mobile/typedarray.js');

  // Store에서 필요한 상태 가져오기
  const pin = useStore.getState().pinSlice.pin;
  const setPin = useStore.getState().pinSlice.setPin;
  const setType = useStore.getState().pinSlice.setType;

  const fnResetOnClick = () => {
    overlay.unmountAll();
    setTimeout(() => {
      navigate(PATHS.mobileVerification, {
        state: {
          ...state,
          verificationType:
            props?.type === PinInteractionMode.로그인 ? VerificationType.FailSetUser : VerificationType.ReSetUser,
        },
      });
    }, 0);
  };

  // 컴포넌트 마운트 시 타입 설정
  useEffect(() => {
    if (props.type) {
      setType(props.type);
    }
  }, [props.type, setType]);

  useEffect(() => {
    if (!isLoading1 && !isLoading2 && !isLoading3 && !isLoading4 && !isLoading5) {
      setTimeout(() => {
        window.initCallback = () => {
          setTimeout(() => {
            inputRef.current && inputRef.current.click();
            const func = document.getElementById('keypadFunc');
            if (func && props) {
              if (props?.type === PinInteractionMode.로그인) {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.textContent = '간편 비밀번호 재설정';
                btn.addEventListener('click', fnResetOnClick);
                func.appendChild(btn);
              }
            }
          }, 10);
        };

        window.initmTranskey();

        window.mTranskey.prototype.startCallBack = function (e: any) {
          setPin((current) => {
            if (current.length < 6) return current + String(e ?? '');
            return current;
          });
        };

        window.mTranskey.prototype.delCallBack = function () {
          setPin((current) => current.slice(0, -1));
        };

        window.mTranskey.prototype.clearCallBack = function () {
          setPin('');
          (window.mtk as any).now.inputObj.value = '';
        };

        window.mTranskey.prototype.relocateCallBack = function () {
          setPin('');
          (window.mtk as any).now.inputObj.value = '';
        };

        window.mTranskey.prototype.doneCallBack = function (e: any) {
          if (inputRef.current) {
            const { id } = inputRef.current;
            const values = (window.mtk as any).inputFillEncData((window.mtk as any).now.inputObj);
            const { hidden } = values;
            const { hmac } = values;
            const { keyboardType } = (window.transkey as any)[id];
            const { keyIndex } = (window.transkey as any)[id];
            const { fieldType } = (window.transkey as any)[id];
            const seedKey = (document.getElementById('seedKey') as HTMLInputElement).value;
            const reqData: TransKeyModel = {
              id,
              hidden,
              hmac: String(hmac),
              keyboardType,
              keyIndex,
              fieldType,
              seedKey,
              initTime: window.initTime,
            };

            setUserRes((prev) => {
              return {
                ...prev,
                transkeyModel: reqData,
              };
            });

            setPin((current) => {
              if (current.length < 6) return current + String(e ?? '');
              return current;
            });
          }
        };
      }, 100);
    }

    return () => {
      if (window.mtk && (window.mtk as any).now && (window.mtk as any).now.inputObj) {
        (window.mtk as any)?.close?.();
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoading1, isLoading2, isLoading3, isLoading4, isLoading5]);

  useEffect(() => {
    // PIN 값이 변경될 때마다 적절한 핸들러 호출
    if (pin.length === 6) {
      const latestTranskeyModel = getLatestTranskeyModel();

      if (latestTranskeyModel) {
        setUserRes((prev) => ({
          ...prev,
          transkeyModel: latestTranskeyModel,
        }));
      }

      const currentType = props.type;

      if (currentType === PinInteractionMode.신규입력) handleCreatePin();
      if (currentType === PinInteractionMode.재설정) handleResetPin();
      // if (currentType === PinInteractionMode.인증) handleInput();
      if (currentType === PinInteractionMode.인증) handleVerifyPin();
      if (currentType === PinInteractionMode.인증_바텀시트) handleInput();
      if (currentType === PinInteractionMode.로그인) handleVerifyPin();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pin]);

  return (
    <div className="absolute bottom-0 left-0 flex h-[60vh] w-full items-end">
      <input
        ref={inputRef}
        type="hidden"
        id="userPin"
        name="userPin"
        data-tk-inputtext="간편 비밀번호 입력"
        data-tk-useinput="true"
        data-tk-bottom="true"
        data-tk-kbdtype="number"
        data-tk-nextsibling="true"
        onClick={(e) => (window.mtk as any)?.onKeyboard(e.target)}
        maxLength={6}
      />
    </div>
  );
});
